from __future__ import annotations

"""
Constants for ZKTeco devices (pyzk protocol wrapper).
"""

# Default connection settings
DEFAULT_PORT = 4370
DEFAULT_TIMEOUT = 10

# User privilege levels
USER_DEFAULT = 0
USER_ENROLLER = 2
USER_MANAGER = 6
USER_ADMIN = 14

# Punch types (attendance states)
