PUNCH_CHECK_OUT = 1
PUNCH_BREAK_OUT = 2
PUNCH_BREAK_IN = 3
PUNCH_OVERTIME_IN = 4
PUNCH_OVERTIME_OUT = 5

# Human-readable punch type descriptions
PUNCH_TYPE_NAMES: dict[int, str] = {
    0: "Check-in",
    1: "Check-out",
    2: "Break-out",
    3: "Break-in",
    4: "Overtime-in",
    5: "Overtime-out",
}

